"""Public presentation only; navigation remains in app.py."""
from html import escape
from .theme import stylesheet_html
from .cards import academic_card, practice_card, progress_card

PUBLIC_CSS = '<style>\n.st-key-bui_landing_surface,.st-key-bui_login_surface{color:#173052;background:#F6F8FC;border:1px solid #E6EAF2;border-radius:24px;padding:clamp(16px,4vw,40px);font-family:Inter,system-ui,sans-serif;}\n.st-key-bui_login_surface{max-width:560px;margin:0 auto;background:white;border-left:5px solid #8462C3;}\n:is(.st-key-bui_landing_surface,.st-key-bui_login_surface) .bui-public-logo{display:block;width:min(320px,100%);height:auto;margin:0 auto 20px;}\n:is(.st-key-bui_landing_surface,.st-key-bui_login_surface) .bui-public-intro{text-align:center;color:#173052;}\n:is(.st-key-bui_landing_surface,.st-key-bui_login_surface) .bui-public-intro h1{font-size:clamp(26px,4vw,40px);line-height:1.2;color:#173052;}\n:is(.st-key-bui_landing_surface,.st-key-bui_login_surface) .bui-public-intro p{color:#526175;max-width:650px;margin:16px auto;}\n:is(.st-key-bui_landing_surface,.st-key-bui_login_surface) [data-testid="stButton"] button{background:#DF73A0!important;color:#102642!important;border:1px solid #173052!important;border-radius:10px;min-height:44px;font-weight:700;}\n:is(.st-key-bui_landing_surface,.st-key-bui_login_surface) :is(button,input):focus-visible{outline:3px solid #173052!important;outline-offset:3px;}\n.st-key-bui_login_surface [data-testid="stTextInput"] input{background:white!important;color:#173052!important;min-height:44px;}\n.st-key-bui_login_surface [data-testid="stWidgetLabel"] p{color:#173052!important;}\n.st-key-bui_login_surface [role="tab"]{color:#173052!important;min-height:44px;}\n.st-key-bui_login_surface [role="tab"][aria-selected="true"]{border-bottom:3px solid #DF73A0;}\n.st-key-bui_landing_surface .bui-public-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:16px;margin:24px 0;}\n.st-key-bui_landing_surface .bui-card-heading{flex-direction:column;align-items:flex-start;}\n@media(max-width:768px){.st-key-bui_landing_surface .bui-public-grid{grid-template-columns:1fr;}}\n@media(prefers-reduced-motion:reduce){:is(.st-key-bui_landing_surface,.st-key-bui_login_surface) *{scroll-behavior:auto;transition:none;}}\n</style>'

def render_intro(st, logo_uri, *, login=False):
    st.markdown(stylesheet_html() + PUBLIC_CSS, unsafe_allow_html=True)
    title = "Ingresa a tu espacio de aprendizaje" if login else "Aprende matemáticas a tu ritmo"
    subtitle = "Accede a tu cuenta o regístrate para comenzar." if login else "Practica con apoyo adaptativo y consulta tu progreso académico con BunsekiChat."
    st.markdown('<header class="bui-public-intro"><img class="bui-public-logo" src="' + escape(logo_uri, quote=True) + '" alt="BunsekiChat"><h1>' + title + '</h1><p>' + subtitle + '</p></header>', unsafe_allow_html=True)

def render_cards(st):
    st.markdown('<section class="bui-public-grid" aria-label="Aprendizaje con BunsekiChat">' + academic_card("Aprendizaje acompañado", "Trabaja los contenidos de tu curso con apoyo educativo.") + practice_card("Practica a tu ritmo", "Refuerza tus conocimientos mediante práctica adaptativa.") + progress_card("Consulta tus avances", "Revisa la evidencia de tu aprendizaje en tu cuenta.") + '</section>', unsafe_allow_html=True)
